bitmap_t fill_val = fill ? static_cast<bitmap_t>(~static_cast<bitmap_t>(0)) : static_cast<bitmap_t>(0);
for (std::size_t i = 0; i < nwords; ++i) {
    bitmap[i] = fill_val;
}
if (fill) {
    std::size_t bits_per_word = sizeof(bitmap_t) * 8;
    std::size_t rem = binfo->nbits % bits_per_word;
    if (rem != 0) {
        bitmap_t mask = (static_cast<bitmap_t>(1) << rem) - static_cast<bitmap_t>(1);
        bitmap[nwords - 1] = mask;
    }
}

